package org.nonfood.oilplants.dao;
import org.nonfood.oilplants.config.Database;
import org.nonfood.oilplants.model.*;
import java.sql.*;import java.util.*;
public class FavoriteDao {
 public void add(long user,long plant)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT IGNORE INTO favorites(user_id,plant_id) VALUES(?,?)")){p.setLong(1,user);p.setLong(2,plant);p.executeUpdate();}}
 public void remove(long user,long plant)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM favorites WHERE user_id=? AND plant_id=?")){p.setLong(1,user);p.setLong(2,plant);p.executeUpdate();}}
 public List<Plant> list(long user)throws SQLException{String q="SELECT p.id,p.genus_id,p.name_zh,p.scientific_name,p.name_en,p.morphology,p.distribution,p.cultivation,p.uses,p.source_pages,p.verification_status,f.family_name_zh,f.family_name_latin,g.genus_name_zh,g.genus_name_latin,im.stored_name,im.alt_text,(SELECT GROUP_CONCAT(CONCAT(COALESCE(s.sample_label,CONCAT('样本#',s.id)),'：',CAST(s.oil_content_pct AS CHAR),'%') ORDER BY s.id SEPARATOR '；') FROM plant_oil_samples s WHERE s.plant_id=p.id AND s.oil_content_status='VERIFIED' AND s.oil_content_pct IS NOT NULL) AS oil_content_summary FROM favorites x JOIN plants p ON p.id=x.plant_id LEFT JOIN plant_genera g ON g.id=p.genus_id LEFT JOIN plant_families f ON f.id=g.family_id LEFT JOIN plant_images im ON im.id=(SELECT ii.id FROM plant_images ii WHERE ii.plant_id=p.id AND ii.is_primary=1 ORDER BY ii.id DESC LIMIT 1) WHERE x.user_id=? ORDER BY x.created_at DESC";List<Plant> out=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,user);try(ResultSet r=p.executeQuery()){while(r.next()){Plant x=new Plant();x.setId(r.getLong("id"));x.setNameZh(r.getString("name_zh"));x.setScientificName(r.getString("scientific_name"));x.setFamilyZh(r.getString("family_name_zh"));x.setGenusZh(r.getString("genus_name_zh"));x.setUses(r.getString("uses"));x.setImageStoredName(r.getString("stored_name"));x.setOilContentSummary(r.getString("oil_content_summary"));out.add(x);}}}return out;}
 public boolean contains(long user,long plant)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM favorites WHERE user_id=? AND plant_id=?")){p.setLong(1,user);p.setLong(2,plant);try(ResultSet r=p.executeQuery()){return r.next();}}}
}
